def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != 0]
    if not points:
        return [row[:] for row in grid]

    # Repeat horizontal bands when the nonzero rows define a complete cycle.
    bands = {}
    for r, row in enumerate(grid):
        values = [v for v in row if v != 0]
        if values and len(set(values)) == 1:
            bands[r] = values[0]
    if len(bands) >= 3:
        for p in range(1, h + 1):
            pattern = {}
            for r, color in bands.items():
                k = r % p
                if k in pattern and pattern[k] != color:
                    break
                pattern[k] = color
            else:
                if len(pattern) == p:
                    return [[pattern[r % p] for _ in range(w)] for r in range(h)]

    # Expand diagonal stripes periodically across the whole grid.
    features = [lambda r, c: r - c, lambda r, c: r + c]
    groups_by_feature = []
    for feature in features:
        groups = {}
        for r, c, color in points:
            groups.setdefault(feature(r, c), []).append(color)
        strength = max(map(len, groups.values()))
        groups_by_feature.append((strength, feature))

    _, feature = max(groups_by_feature, key=lambda item: item[0])
    colors = [color for _, _, color in points]

    for p in range(1, max(h, w) + 1):
        pattern = {}
        for r, c, color in points:
            k = feature(r, c) % p
            if k in pattern and pattern[k] != color:
                break
            pattern[k] = color
        else:
            if len(pattern) >= 2:
                fallback = max(set(colors), key=colors.count)
                return [[pattern.get(feature(r, c) % p, fallback)
                         for c in range(w)] for r in range(h)]

    return [row[:] for row in grid]
